// check24.js for climb batch 24, made from plan-23/manifest/check23.js.
// Checks the MANIFEST block of climb batch 24 (gen24.py's output, $OUT24/manifest24.js) spliced into a scratch copy
// of the workflow script, and with --write splices it into the tracked script. As check23.js: node --check on the
// original and the spliced copy; both parsed as the body of an async function, as the Workflow harness parses them,
// their export made const; every line outside the block byte-identical; the block evaluated with the script's own
// load checks and scatter order; the batch's rungs (lists24.py's IDS, F, Z, S, K, W, G, and H once its lists are
// filled, in that order, less any that --without names), their fields, no rung bringing a gate step, declaring a
// checker count, a crash or a ladder move, or landing only with another; each section equal to the rung's section 3
// of the record (backticks dropped, the ellipsis character as three full stops); briefing, reasons and checks equal
// to lists24.py's, one reason per key, checks a sub-list of the briefing; no rung's test the stage; every section
// naming the count stage and the distance stage; every section saying it makes no speed pass and naming no P-148,
// since no rung changes the checker (rung G changes the code generator, which the stages do not run); no backtick or
// non-ASCII character in any string the agents read; no text asking a skeptic to see a failure again or a stage
// re-run without a code change (the coordinator skill's references/batch.md, "The workflow"); no LEDGER_FROM; the
// record holding no copy of the block. Its last lines say whether the tracked script's block equals the generated
// one, and count the problems.
//   node check24.js [--without <rung>]... [--write] [RECORD]      RECORD defaults to explorations/coordinator/CLIMB-BATCH-24.md
// --without <rung> checks the block that gen24.py writes with the same argument: the batch's rungs less that one.
const fs = require('fs')
const cp = require('child_process')
const path = require('path')
const ROOT = process.env.FORTRESS_HOME || path.resolve(__dirname, '../../../..')
const HERE = process.env.OUT24 || path.join(ROOT, 'tmp')
const SRC = path.join(ROOT, 'explorations/coordinator/climb-batch-workflow.js')
const argv = process.argv.slice(2)
const WRITE = argv.includes('--write')
const WITHOUT = argv.map((a, i) => argv[i - 1] === '--without' ? a : null).filter(a => a !== null)
const BATCH_NAME = '24'
const idsPy = cp.spawnSync('python3', ['-B', '-c', 'import sys; sys.path.insert(0, sys.argv[1]); from lists24 import IDS; print(",".join(IDS))', __dirname], { encoding: 'utf8' })
if (idsPy.status !== 0) { console.log('lists24.py not read: ' + idsPy.stderr.trim().slice(0, 300)); process.exit(2) }
const ALL_IDS = idsPy.stdout.trim().split(',')
const RUN_IDS = ALL_IDS.filter(x => !WITHOUT.includes(x))
if (WITHOUT.some(x => !ALL_IDS.includes(x))) { console.log('--without names a rung not in the batch'); process.exit(2) }
const STAGE_RUNGS = []
const CHECKER_RUNGS = []
const LANDS_ONLY_WITH = Object.fromEntries(ALL_IDS.map(x => [x, []]))
const REC = argv.filter((a, i) => !a.startsWith('--') && argv[i - 1] !== '--without')[0] || path.join(ROOT, 'explorations/coordinator/CLIMB-BATCH-24.md')
const block = fs.readFileSync(path.join(HERE, 'manifest' + BATCH_NAME + '.js'), 'utf8')
const orig = fs.readFileSync(SRC, 'utf8')
